1	/**
2	 * useGatewayWebSocket
3	 *
4	 * Connects to the bot gateway's `/ws/events` WebSocket endpoint and routes
5	 * incoming nia.event envelopes through the existing `routeNiaEvent` system.
6	 *
7	 * This allows PearlOS UI tools to work WITHOUT an active Daily.co room —
8	 * the gateway broadcasts events over both Daily app-messages and this
9	 * WebSocket channel, and the frontend accepts from whichever is available.
10	 *
11	 * Features:
12	 *   - Auto-reconnect with exponential backoff (1s → 30s)
13	 *   - Deduplication by (seq, ts) to avoid double-processing when both
14	 *     Daily and WebSocket are active simultaneously
15	 *   - Cleans up on unmount
16	 */
17	
18	import { useEffect, useRef } from 'react';
19	
20	import { routeNiaEvent } from '@interface/features/DailyCall/events/niaEventRouter';
21	import type { AppMessageEnvelope } from '@interface/features/DailyCall/events/appMessageBridge';
22	import { isDuplicateEvent } from '@interface/lib/event-dedup';
23	
24	const BRIDGE_KIND = 'nia.event';
25	
26	function isNiaEnvelope(obj: unknown): obj is AppMessageEnvelope {
27	  return !!obj && typeof obj === 'object' && (obj as any).kind === BRIDGE_KIND && typeof (obj as any).event === 'string';
28	}
29	
30	export interface UseGatewayWebSocketOptions {
31	  /** Full URL to the gateway, e.g. "http://localhost:4444". Derived from NEXT_PUBLIC_BOT_CONTROL_BASE_URL by default. */
32	  gatewayUrl?: string;
33	  /** Disable the WebSocket entirely */
34	  disabled?: boolean;
35	  /** Optional session ID (e.g. Daily room name) to scope events to a specific session. */
36	  sessionId?: string;
37	}
38	
39	export function useGatewayWebSocket(options: UseGatewayWebSocketOptions = {}) {
40	  const wsRef = useRef<WebSocket | null>(null);
41	  const retriesRef = useRef(0);
42	  const unmountedRef = useRef(false);
43	
44	  useEffect(() => {
45	    if (options.disabled) return;
46	    unmountedRef.current = false;
47	
48	    let baseUrl =
49	      options.gatewayUrl ||
50	      process.env.NEXT_PUBLIC_BOT_CONTROL_BASE_URL ||
51	      '';
52	
53	    if (!baseUrl) return;
54	
55	    // If the env var points to localhost but the page is loaded from a remote
56	    // host, derive the gateway URL from the page's origin.  This handles
57	    // RunPod-style proxies where the port is encoded in the hostname
58	    // (e.g. {pod}-4444.proxy.runpod.net) as well as standard deployments.
59	    if (typeof window !== 'undefined') {
60	      try {
61	        const envUrl = new URL(baseUrl);
62	        const pageHost = window.location.hostname;
63	        if (
64	          (envUrl.hostname === 'localhost' || envUrl.hostname === '127.0.0.1') &&
65	          pageHost !== 'localhost' &&
66	          pageHost !== '127.0.0.1'
67	        ) {
68	          // Non-localhost page: use same-origin rewrite path.
69	          // Next.js rewrites /gateway-ws/* to localhost:4444/ws/*.
70	          // Direct port-based connections (e.g. RunPod {pod}-4444.proxy.runpod.net)
71	          // fail because external proxies don't expose port 4444.
72	          const wsProto = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
73	          baseUrl = `${wsProto}//${window.location.host}/gateway-ws`;
74	        }
75	      } catch {
76	        // leave baseUrl as-is
77	      }
78	    }
79	
80	    // Convert http(s) to ws(s)
81	    const wsUrl = baseUrl.replace(/^http/, 'ws').replace(/\/$/, '') + '/ws/events';
82	
83	    let timer: ReturnType<typeof setTimeout> | null = null;
84	
85	    function connect() {
86	      if (unmountedRef.current) return;
87	
88	      let ws: WebSocket;
89	      try {
90	        ws = new WebSocket(wsUrl);
91	      } catch (err) {
92	        console.error('[gateway-ws] Failed to construct WebSocket (mixed content?)', wsUrl, err);
93	        return;
94	      }
95	      wsRef.current = ws;
