11	
12	import { getClientLogger } from '@interface/lib/client-logger';
13	
14	import { routeNiaEvent } from '../events/niaEventRouter';
15	import { isDuplicateEvent } from '@interface/lib/event-dedup';
16	
17	const log = getClientLogger('[gateway_ws]');
18	
19	/** Derive the WebSocket URL from the bot control base URL env var.
20	 *
21	 * Strategy:
22	 * 1. If the page is served through a tunnel/proxy (not localhost, not RunPod),
23	 *    use same-origin `/gateway-ws/events` path — Next.js rewrites proxy it
24	 *    to localhost:4444.  This avoids cross-origin and mixed-content issues.
25	 * 2. If the page is on a RunPod proxy host, rewrite the port segment.
26	 * 3. Otherwise, use the env var directly with protocol adjustment.
27	 */
28	function getWsUrl(): string | null {
29	  const base =
30	    (typeof process !== 'undefined' && process.env?.NEXT_PUBLIC_BOT_CONTROL_BASE_URL) || '';
31	  if (!base) return null;
32	  try {
33	    const url = new URL(base);
34	
35	    if (typeof window !== 'undefined') {
36	      const pageHost = window.location.hostname;
37	      const pageProto = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
38	
39	      // Non-localhost page (RunPod proxy, Cloudflare tunnel, etc.):
40	      // Always use same-origin rewrite path (/gateway-ws/events).
41	      // Next.js rewrites proxy this to localhost:4444/ws/events.
42	      // Direct port-based connections (e.g. {pod}-4444.proxy.runpod.net)
43	      // fail because RunPod doesn't expose port 4444 externally.
44	      if (pageHost !== 'localhost' && pageHost !== '127.0.0.1') {
45	        return `${pageProto}//${window.location.host}/gateway-ws/events`;
46	      }
47	    }
48	
49	    // Localhost or SSR: connect directly to the gateway
50	    const protocol =
51	      (typeof window !== 'undefined' && window.location.protocol === 'https:') ||
52	      url.protocol === 'https:'
53	        ? 'wss:'
54	        : 'ws:';
55	    return `${protocol}//${url.host}/ws/events`;
56	  } catch {
57	    return null;
58	  }
59	}
60	
61	const RECONNECT_INTERVAL_MS = 3000;
62	const MAX_RECONNECT_INTERVAL_MS = 30000;
63	
64	export interface UseGatewaySocketOptions {
65	  /** Optional session ID (e.g. Daily room name) to scope WebSocket events. */
66	  sessionId?: string;
67	}
68	
69	export function useGatewaySocket(options: UseGatewaySocketOptions = {}) {
70	  const { sessionId } = options;
71	  const wsRef = useRef<WebSocket | null>(null);
72	  const reconnectTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
73	  const reconnectDelay = useRef(RECONNECT_INTERVAL_MS);
74	  const mountedRef = useRef(true);
75	
76	  useEffect(() => {
77	    mountedRef.current = true;
78	    const wsUrl = getWsUrl();
79	    if (!wsUrl) {
80	      log.warn('No NEXT_PUBLIC_BOT_CONTROL_BASE_URL set; gateway WebSocket disabled');
81	      return;
82	    }
83	
84	    function connect() {
85	      if (!mountedRef.current) return;
86	      if (wsRef.current?.readyState === WebSocket.OPEN || wsRef.current?.readyState === WebSocket.CONNECTING) {
87	        return;
88	      }
89	
90	      log.info('Connecting to gateway WebSocket', { url: wsUrl, sessionId });
91	      let ws: WebSocket;
92	      try {
93	        ws = new WebSocket(wsUrl!);
94	      } catch (err) {
95	        log.error('Failed to construct WebSocket (mixed content?)', { url: wsUrl, error: String(err) });
96	        return;
97	      }
98	      wsRef.current = ws;
99	
