1	'use client';
2	
3	/**
4	 * WsEventBridgeManager
5	 *
6	 * Automatically starts the WebSocket event bridge when no Daily call is active,
7	 * so PearlOS tool events (notes, YouTube, windows, soundtrack, etc.) work in
8	 * desktop mode without a video call.
9	 *
10	 * When a Daily call joins, the bridge is stopped (Daily app-messages take over).
11	 * When the call ends, the bridge restarts.
12	 */
13	
14	import { useEffect } from 'react';
15	
16	import { getClientLogger } from '@interface/lib/client-logger';
17	
18	import { useDailyCallState } from '../state/store';
19	
20	const log = getClientLogger('[ws_bridge_mgr]');
21	
22	/** Derive a room name from a Daily room URL. */
23	function extractRoomName(roomUrl?: string): string | undefined {
24	  if (!roomUrl) return undefined;
25	  try {
26	    const url = new URL(roomUrl);
27	    const parts = url.pathname.split('/').filter(Boolean);
28	    return parts[parts.length - 1] || undefined;
29	  } catch {
30	    return undefined;
31	  }
32	}
33	
34	export function WsEventBridgeManager() {
35	  const { joined, roomUrl } = useDailyCallState();
36	
37	  useEffect(() => {
38	    // Always keep the WS bridge running — it provides near-instant event
39	    // delivery.  When a Daily call is also active, events may arrive via
40	    // both Daily app-message AND WebSocket; the dedup layer in
41	    // event-dedup.ts ensures each envelope is processed only once.
42	    //
43	    // Previously the bridge was stopped during calls, but this caused
44	    // 30+ second delays because the Daily HTTP REST send-app-message
45	    // path is slow.  Keeping both paths active means whichever arrives
46	    // first wins and the duplicate is silently dropped.
47	    const sessionId = extractRoomName(roomUrl);
48	    import('../events/wsEventBridge').then(({ startWsEventBridge }) => {
49	      log.info('Starting/ensuring WS event bridge', { sessionId, dailyJoined: joined });
50	      startWsEventBridge(undefined, sessionId);
51	    });
52	
53	    return () => {
54	      // Cleanup on unmount
55	      import('../events/wsEventBridge').then(({ stopWsEventBridge }) => {
56	        stopWsEventBridge();
57	      });
58	    };
59	  }, [joined, roomUrl]);
60	
61	  return null;
62	}
63

