10	const INITIAL_LIMIT = 10;
11	const PAGE_SIZE = 10;
12	
13	/**
14	 * Strip large HTML blocks that leak from tool call arguments into the text stream.
15	 * Wonder Canvas scenes generate HTML that sometimes appears in the chat content
16	 * when the LLM echoes tool arguments as text. This strips those blocks while
17	 * preserving normal conversational text that may contain minor inline tags.
18	 */
19	function stripLeakedHtml(text: string): string {
20	  // Detect if the text is predominantly HTML (has multiple tags, style blocks, etc.)
21	  const tagCount = (text.match(/<[a-z][^>]*>/gi) || []).length;
22	  const hasStyleBlock = /<style[\s>]/i.test(text);
23	  const hasDivStructure = /<div[\s>]/i.test(text) && /<\/div>/i.test(text);
24	  const hasDataAction = /data-action=/i.test(text);
25	  const hasWonderClass = /wonder-/i.test(text) && tagCount > 3;
26	  // Catch inline-styled HTML blocks (common in wonder canvas scenes)
27	  const hasInlineStyles = /style\s*=\s*["'][^"']*(?:background|gradient|display\s*:\s*flex|min-height|font-size)/i.test(text);
28	  const hasHtmlBoilerplate = /<!DOCTYPE|<html|<head|<body/i.test(text);
29	
30	  // If it looks like a Wonder Canvas HTML block or any substantial HTML, strip it
31	  if (
32	    (tagCount > 5 && (hasStyleBlock || hasDivStructure)) ||
33	    (tagCount > 2 && hasInlineStyles) ||
34	    hasDataAction ||
35	    hasWonderClass ||
36	    hasHtmlBoilerplate
37	  ) {
38	    const htmlStartMatch = text.match(/^([\s\S]*?)(?:<(?:!DOCTYPE|div|style|section|main|html|body|head)\b)/i);
39	    const preText = htmlStartMatch?.[1]?.trim() || '';
40	    const htmlEndMatch = text.match(/<\/(?:div|style|section|main|html|body|head)>[^<]*$/i);
41	    const postIdx = htmlEndMatch ? (htmlEndMatch.index ?? 0) + htmlEndMatch[0].length : -1;
42	    const postText = postIdx > 0 ? text.slice(postIdx).replace(/<[^>]+>/g, '').trim() : '';
43	
44	    const result = [preText, postText].filter(Boolean).join(' ').trim();
45	    return result || text;
46	  }
47	
48	  return text;
49	}
