52	  const [messages, setMessages] = useState<ChatMessage[]>([]);
53	  const [isTyping, setIsTyping] = useState(false);
54	  const [historyLoaded, setHistoryLoaded] = useState(false);
55	  /** True while we're fetching an older page (infinite scroll up). */
56	  const [isLoadingMore, setIsLoadingMore] = useState(false);
57	  /** Becomes true when the server returns fewer messages than PAGE_SIZE (nothing left). */
58	  const [hasMore, setHasMore] = useState(true);
59	  const abortRef = useRef<AbortController | null>(null);
60	
61	  // ─── Initial history load (last N messages) ───
62	  useEffect(() => {
63	    if (historyLoaded) return;
