70	        if (cancelled || !data.messages?.length) {
71	          // If we got nothing, there's no more history to load either
72	          if (!cancelled) setHasMore(false);
73	          return;
74	        }
75	        const loaded: ChatMessage[] = data.messages.map((m: any) => ({
76	          id: crypto.randomUUID(),
77	          role: m.role as 'user' | 'assistant',
78	          content: m.content,
79	          timestamp: m.timestamp ? new Date(m.timestamp).getTime() : Date.now(),
80	          isStreaming: false,
81	        }));
82	        setMessages(loaded);
