1	import { NextRequest } from 'next/server';
2	import { requireAuth } from '@interface/lib/api-auth';
3	
4	const BOT_GATEWAY_URL = process.env.BOT_GATEWAY_URL || process.env.NEXT_PUBLIC_BOT_CONTROL_BASE_URL || 'http://localhost:4444';
5	
6	export async function POST(req: NextRequest) {
7	  const authError = await requireAuth(req);
8	  if (authError) return authError;
9	  try {
10	    const body = await req.json();
11	    const upstream = await fetch(`${BOT_GATEWAY_URL}/api/chat`, {
12	      method: 'POST',
13	      headers: { 'Content-Type': 'application/json' },
14	      body: JSON.stringify(body),
15	    });
16	
17	    if (!upstream.ok) {
18	      return new Response(JSON.stringify({ error: `Upstream error: ${upstream.status}` }), {
19	        status: upstream.status,
20	        headers: { 'Content-Type': 'application/json' },
21	      });
22	    }
23	
24	    // Stream the SSE response through
25	    return new Response(upstream.body, {
26	      status: 200,
27	      headers: {
28	        'Content-Type': 'text/event-stream',
29	        'Cache-Control': 'no-cache',
30	        Connection: 'keep-alive',
31	      },
32	    });
33	  } catch (err: any) {
34	    return new Response(JSON.stringify({ error: err.message }), {
35	      status: 502,
36	      headers: { 'Content-Type': 'application/json' },
37	    });
38	  }
39	}
