1	
2	/**
3	 * Server-side utility for sending admin messages to the bot control server.
4	 * Shared by API routes and Server Actions.
5	 */
6	
7	// Use same configuration logic as joinImpl.ts to ensure consistency
8	const BOT_CONTROL_BASE_URL = (process.env.BOT_CONTROL_BASE_URL || process.env.NEXT_PUBLIC_BOT_CONTROL_BASE_URL || '').replace(/\/$/, '');
9	
10	import { getLogger } from './logger';
11	
12	export interface SendBotMessageParams {
13	  roomUrl: string;
14	  message: string;
15	  mode?: 'queued' | 'immediate';
16	  senderId?: string;
17	  senderName?: string;
18	  tenantId?: string;
19	  sessionId?: string;
20	  /** Optional context for message attribution (e.g., sourceType: 'user-text') */
21	  context?: Record<string, unknown>;
22	  /** Optional server-only headers (claims/signature, correlation IDs). */
23	  extraHeaders?: Record<string, string>;
24	}
25	
26	/**
27	 * Sends a message to the bot control server.
28	 * 
29	 * @param params - The message parameters
30	 * @returns Promise resolving to the response from the bot server
31	 */
32	export async function sendBotMessage(params: SendBotMessageParams): Promise<Response> {
33	  const log = getLogger('[bot-messaging]');
34	  const {
35	    roomUrl,
36	    message,
37	    mode = 'queued',
38	    senderId = 'system',
39	    senderName = 'System',
40	    tenantId,
41	    sessionId,
42	    context,
43	    extraHeaders,
44	  } = params;
45	
46	  if (!BOT_CONTROL_BASE_URL) {
47	    log.error('BOT_CONTROL_BASE_URL is not configured');
48	    throw new Error('Bot control URL is not configured');
49	  }
50	
51	  if (!roomUrl) {
52	    log.warn('No room URL provided, skipping message send');
53	    // Return a mock response to avoid breaking the flow if room URL is missing
54	    return new Response(JSON.stringify({ skipped: true, reason: 'no_room_url' }), { status: 200 });
55	  }
56	
57	  const payload: Record<string, unknown> = {
58	    room_url: roomUrl,
59	    message: message.trim(),
60	    mode,
61	    sender_id: senderId,
62	    sender_name: senderName,
63	    tenant_id: tenantId,
64	    sessionId,
65	    timestamp: Date.now()
66	  };
67	  
68	  // Add context if provided (for user text attribution, etc.)
69	  if (context) {
70	    payload.context = context;
71	  }
72	
73	  log.info('Forwarding admin message to bot server', {
74	    mode,
75	    roomUrl,
76	    sender: senderName,
77	    messageLength: message.trim().length,
78	  });
79	
80	  const headers: Record<string, string> = {
81	    'Content-Type': 'application/json',
82	  };
83	
84	  if (process.env.BOT_CONTROL_SHARED_SECRET) {
85	    headers['X-Bot-Secret'] = process.env.BOT_CONTROL_SHARED_SECRET;
86	  }
87	  if (extraHeaders) {
88	    Object.assign(headers, extraHeaders);
89	  }
90	
91	  try {
92	    const response = await fetch(`${BOT_CONTROL_BASE_URL}/admin`, {
93	      method: 'POST',
94	      headers,
95	      body: JSON.stringify(payload),
96	    });
97	
98	    if (!response.ok) {
99	      const errorText = await response.text();
100	      log.error('Bot server error response', {
101	        status: response.status,
102	        bodyLength: errorText?.length ?? 0,
103	      });
104	      // We don't throw here to allow the caller to handle the response object
105	    }
106	
107	    return response;
108	  } catch (error) {
109	    log.error('Fetch failed when sending admin message', { error });
110	    throw error;
111	  }
112	}
