2	 * useGatewayWebSocket
3	 *
4	 * Connects to the bot gateway's `/ws/events` WebSocket endpoint and routes
5	 * incoming nia.event envelopes through the existing `routeNiaEvent` system.
6	 *
7	 * This allows PearlOS UI tools to work WITHOUT an active Daily.co room —
8	 * the gateway broadcasts events over both Daily app-messages and this
9	 * WebSocket channel, and the frontend accepts from whichever is available.
10	 *
11	 * Features:
12	 *   - Auto-reconnect with exponential backoff (1s → 30s)
13	 *   - Deduplication by (seq, ts) to avoid double-processing when both
14	 *     Daily and WebSocket are active simultaneously
15	 *   - Cleans up on unmount
16	 */
17	
18	import { useEffect, useRef } from 'react';
19	
20	import { routeNiaEvent } from '@interface/features/DailyCall/events/niaEventRouter';
21	import type { AppMessageEnvelope } from '@interface/features/DailyCall/events/appMessageBridge';
22	import { isDuplicateEvent } from '@interface/lib/event-dedup';
23	
24	const BRIDGE_KIND = 'nia.event';
25	
26	function isNiaEnvelope(obj: unknown): obj is AppMessageEnvelope {
27	  return !!obj && typeof obj === 'object' && (obj as any).kind === BRIDGE_KIND && typeof (obj as any).event === 'string';
28	}
29	
30	export interface UseGatewayWebSocketOptions {
31	  /** Full URL to the gateway, e.g. "http://localhost:4444". Derived from NEXT_PUBLIC_BOT_CONTROL_BASE_URL by default. */
32	  gatewayUrl?: string;
33	  /** Disable the WebSocket entirely */
34	  disabled?: boolean;
35	  /** Optional session ID (e.g. Daily room name) to scope events to a specific session. */
36	  sessionId?: string;
37	}
38	
