3	import React, { useEffect, useRef, ReactNode } from 'react';
4	import { useKeyboardHeight } from '@interface/hooks/useKeyboardHeight';
5	import styles from './ChatModeLayout.module.css';
6	interface ChatModeLayoutProps {
7	  /** Chat messages content */
8	  children: ReactNode;
9	  /** Input bar content — rendered at bottom, above keyboard */
10	  inputBar?: ReactNode;
11	  /** Class name for the outer container */
12	  className?: string;
13	}
14	
15	/**
16	 * Mobile-aware layout wrapper for chat mode.
17	 *
18	 * Handles:
19	 * - iOS Safari keyboard accommodation via visualViewport
20	 * - Body scroll lock when chat is open
21	 * - Safe area insets (notch, home indicator)
22	 * - Smooth keyboard transitions
23	 * - Auto-scroll to bottom on new messages
24	 */
25	export function ChatModeLayout({ children, inputBar, className }: ChatModeLayoutProps) {
26	  const { keyboardHeight, isKeyboardOpen, isIOS, viewportHeight } = useKeyboardHeight();
27	  const containerRef = useRef<HTMLDivElement>(null);
28	  const messagesRef = useRef<HTMLDivElement>(null);
29	
30	  // Lock body scroll when mounted
31	  useEffect(() => {
32	    const body = document.body;
33	    const originalOverflow = body.style.overflow;
34	    const originalPosition = body.style.position;
35	    body.style.overflow = 'hidden';
36	    body.style.position = 'fixed';
37	    body.style.width = '100%';
38	
39	    return () => {
40	      body.style.overflow = originalOverflow;
41	      body.style.position = originalPosition;
42	      body.style.width = '';
43	    };
44	  }, []);
45	
46	  // On iOS, set container height to visualViewport height
47	  // This avoids the 100vh-includes-keyboard-area problem
48	  useEffect(() => {
49	    if (!isIOS || !containerRef.current) return;
50	    containerRef.current.style.height = `${viewportHeight}px`;
51	  }, [isIOS, viewportHeight]);
52	
53	  // Auto-scroll messages to bottom when keyboard opens
54	  useEffect(() => {
55	    if (isKeyboardOpen && messagesRef.current) {
56	      // Small delay lets layout settle
57	      requestAnimationFrame(() => {
58	        messagesRef.current?.scrollTo({
59	          top: messagesRef.current.scrollHeight,
60	          behavior: 'smooth',
61	        });
62	      });
63	    }
64	  }, [isKeyboardOpen]);
65	
66	  return (
67	    <div
68	      ref={containerRef}
69	      className={`${styles.container} ${className ?? ''}`}
70	    >
71	      <div ref={messagesRef} className={styles.messages}>
72	        {children}
73	      </div>
74	
75	      {inputBar && (
76	        <div
77	          className={`${styles.inputBar} ${isKeyboardOpen ? styles.inputBarKeyboardOpen : ''}`}
78	          onMouseDown={(e) => {
79	            // Don't prevent default on the actual input/textarea
80	            const target = e.target as HTMLElement;
81	            if (target.tagName !== 'INPUT' && target.tagName !== 'TEXTAREA') {
82	              e.preventDefault();
83	            }
84	          }}
85	        >
86	          {inputBar}
87	        </div>
88	      )}
89	    </div>
90	  );
91	}
