14	        'Stay in persona (doctor/painter/etc. as described).',
15	        'Do not include speech bubbles, emoji, ASCII art, or code.',
16	    ].join(' ');
17	}
18	
19	type LLMProvider = 'ollama' | 'openai';
20	
21	interface LLMConfig {
22	    provider: LLMProvider;
23	    baseUrl: string;
24	    model: string;
25	    apiKey?: string;
26	}
27	
28	function getLLMConfig(): LLMConfig | null {
29	    // Try Ollama first
30	    const ollamaUrl = process.env.OLLAMA_BASE_URL || process.env.SPRITE_CHAT_LLM_URL;
31	    if (ollamaUrl) {
32	        return {
33	            provider: 'ollama',
34	            baseUrl: ollamaUrl.endsWith('/') ? ollamaUrl.slice(0, -1) : ollamaUrl,
35	            model: OLLAMA_MODEL,
36	        };
37	    }
38	    
39	    // Prefer OpenClaw (Claude) over OpenAI
40	    const openclawKey = process.env.OPENCLAW_API_KEY;
41	    if (openclawKey) {
42	        return {
43	            provider: 'openai',
44	            baseUrl: process.env.OPENCLAW_API_URL || 'http://localhost:18789/v1',
45	            model: OPENAI_MODEL,
46	            apiKey: openclawKey,
47	        };
48	    }
49	
50	    // Fall back to OpenAI
51	    const openaiKey = process.env.OPENAI_API_KEY;
52	    if (openaiKey) {
53	        return {
54	            provider: 'openai',
55	            baseUrl: 'https://api.openai.com/v1',
56	            model: OPENAI_MODEL,
57	            apiKey: openaiKey,
58	        };
59	    }
60	    
61	    return null;
62	}
