68	        body: JSON.stringify({
69	            model: config.model,
70	            stream: false,
71	            messages: [
72	                { role: 'system', content: systemPrompt },
73	                { role: 'user', content: message },
74	            ],
75	        }),
76	    });
77	
78	    if (!res.ok) {
79	        const text = await res.text().catch(() => '');
80	        throw new Error(`Ollama request failed: ${res.status} - ${text.slice(0, 200)}`);
81	    }
82	
83	    const data = await res.json().catch(() => null);
84	    const reply = data?.message?.content;
85	    
86	    if (!reply || typeof reply !== 'string') {
87	        throw new Error('Invalid Ollama response structure');
88	    }
89	    
90	    return reply;
91	}
