2	 * OpenClaw Bridge API Route
3	 * SECURITY: Proxies OpenClaw requests server-side so the API key is never exposed to the browser.
4	 *
5	 * POST /api/openclaw-bridge
6	 *   Body: { prompt, assistantId, conversationId?, workspacePath? }
7	 *   Proxies to OpenClaw's /v1/chat/completions endpoint and returns SSE stream
8	 *
9	 * GET /api/openclaw-bridge
10	 *   Health check — returns { ok: true } if OpenClaw gateway is reachable
11	 */
12	
13	import { NextRequest, NextResponse } from 'next/server';
14	import { readFileSync } from 'fs';
15	import { join } from 'path';
16	import { homedir } from 'os';
17	
18	function getConfig() {
19	  const apiUrl = process.env.OPENCLAW_API_URL ?? 'http://localhost:3100';
20	  const apiKey = process.env.OPENCLAW_API_KEY ?? '';
21	  return { apiUrl, apiKey };
22	}
23	
24	function getPrimaryModel(): string {
25	  const fallback = 'anthropic/claude-sonnet-4-5';
26	  try {
27	    const configPath = process.env.OPENCLAW_CONFIG_PATH ?? join(homedir(), '.openclaw', 'openclaw.json');
28	    const raw = readFileSync(configPath, 'utf-8');
29	    const config = JSON.parse(raw);
30	    return config?.agents?.defaults?.model?.primary ?? fallback;
31	  } catch {
32	    return fallback;
33	  }
34	}
35	
36	export async function GET() {
37	  const { apiUrl } = getConfig();
38	  try {
39	    const res = await fetch(`${apiUrl}/health`, { method: 'GET' });
40	    return NextResponse.json({ ok: res.ok });
41	  } catch {
42	    return NextResponse.json({ ok: false });
43	  }
44	}
45	
46	export async function POST(req: NextRequest) {
47	  const body = await req.json();
48	  const { prompt, assistantId, conversationId } = body;
49	
50	  if (!prompt) {
51	    return NextResponse.json(
52	      { error: 'prompt is required' },
53	      { status: 400 }
54	    );
55	  }
56	
57	  const { apiUrl, apiKey } = getConfig();
58	
59	  // Stream response via SSE by proxying to OpenClaw's /v1/chat/completions
60	  const encoder = new TextEncoder();
61	  const stream = new ReadableStream({
62	    async start(controller) {
63	      try {
64	        const response = await fetch(`${apiUrl}/v1/chat/completions`, {
65	          method: 'POST',
66	          headers: {
67	            'Content-Type': 'application/json',
68	            Authorization: `Bearer ${apiKey}`,
69	            Accept: 'text/event-stream',
70	          },
71	          body: JSON.stringify({
72	            model: getPrimaryModel(),
73	            messages: [{ role: 'user', content: prompt }],
74	            stream: true,
75	          }),
76	        });
77	
78	        if (!response.ok || !response.body) {
79	          controller.enqueue(
80	            encoder.encode(
81	              `data: ${JSON.stringify({ type: 'error', content: `OpenClaw API error: ${response.status}` })}\n\n`
82	            )
83	          );
84	          controller.close();
85	          return;
86	        }
87	
88	        const reader = response.body.getReader();
89	        const decoder = new TextDecoder();
90	        let buffer = '';
91	
92	        while (true) {
93	          const { done, value } = await reader.read();
94	          if (done) break;
95	
96	          buffer += decoder.decode(value, { stream: true });
97	          const lines = buffer.split('\n');
98	          buffer = lines.pop() ?? '';
99	
100	          for (const line of lines) {
101	            if (line.startsWith('data: ')) {
102	              const data = line.slice(6).trim();
103	              if (data === '[DONE]') {
104	                controller.enqueue(encoder.encode('data: [DONE]\n\n'));
105	                controller.close();
106	                return;
107	              }
108	              try {
109	                const parsed = JSON.parse(data);
110	                const content = parsed?.choices?.[0]?.delta?.content;
