1	/**
2	 * OpenClaw Config API
3	 * GET  — read OpenClaw config from ~/.openclaw/openclaw.json
4	 * POST — deep-merge patch into OpenClaw config
5	 *
6	 * Special handling:
7	 * - agents.list updates merge by agent id (find and update, don't replace entire array)
8	 * - _updateAgentModel: { id: string, model: string } shortcut for updating a specific agent's model
9	 */
10	import { NextRequest, NextResponse } from 'next/server';
11	import { readFile, writeFile } from 'fs/promises';
12	import { homedir } from 'os';
13	import { join } from 'path';
14	import { requireAuth } from '@interface/lib/api-auth';
15	
16	const CONFIG_PATH = process.env.OPENCLAW_CONFIG_PATH ?? join(homedir(), '.openclaw', 'openclaw.json');
17	const SESSIONS_PATH = process.env.OPENCLAW_SESSIONS_PATH ?? join(homedir(), '.openclaw', 'agents', 'main', 'sessions', 'sessions.json');
18	
19	interface AgentConfig {
20	  id: string;
21	  name?: string;
22	  model?: { primary?: string };
23	  workspace?: string;
24	  [key: string]: unknown;
25	}
26	
27	function deepMerge(target: Record<string, unknown>, source: Record<string, unknown>): Record<string, unknown> {
28	  const result = { ...target };
29	  for (const key of Object.keys(source)) {
30	    // Special handling for agents.list: merge by agent id
31	    if (key === 'list' && Array.isArray(source[key]) && Array.isArray(target[key])) {
32	      const sourceList = source[key] as AgentConfig[];
33	      const targetList = [...(target[key] as AgentConfig[])] as AgentConfig[];
34	      
35	      for (const sourceAgent of sourceList) {
36	        const existingIdx = targetList.findIndex(a => a.id === sourceAgent.id);
37	        if (existingIdx >= 0) {
38	          // Deep merge the existing agent with the source agent
39	          targetList[existingIdx] = deepMerge(
40	            targetList[existingIdx] as Record<string, unknown>,
41	            sourceAgent as Record<string, unknown>
42	          ) as AgentConfig;
43	        } else {
44	          // New agent, add it
45	          targetList.push(sourceAgent);
46	        }
47	      }
48	      result[key] = targetList;
49	    } else if (
50	      source[key] && typeof source[key] === 'object' && !Array.isArray(source[key]) &&
51	      target[key] && typeof target[key] === 'object' && !Array.isArray(target[key])
52	    ) {
53	      result[key] = deepMerge(target[key] as Record<string, unknown>, source[key] as Record<string, unknown>);
54	    } else {
55	      result[key] = source[key];
56	    }
57	  }
58	  return result;
59	}
60	
61	export async function GET(request: NextRequest) {
62	  const authError = await requireAuth(request);
63	  if (authError) return authError;
64	  try {
65	    const raw = await readFile(CONFIG_PATH, 'utf-8');
66	    const config = JSON.parse(raw);
67	    return NextResponse.json(config);
68	  } catch (error) {
69	    return NextResponse.json(
70	      { error: 'Failed to read OpenClaw config', detail: String(error) },
71	      { status: 500 }
72	    );
73	  }
74	}
75	
76	export async function POST(request: NextRequest) {
77	  const authError = await requireAuth(request);
78	  if (authError) return authError;
79	  try {
80	    const body = await request.json();
81	    const patch = body.patch;
82	    if (!patch || typeof patch !== 'object') {
83	      return NextResponse.json({ error: 'Missing "patch" object in body' }, { status: 400 });
84	    }
85	
86	    const raw = await readFile(CONFIG_PATH, 'utf-8');
87	    const config = JSON.parse(raw);
88	    const merged = deepMerge(config, patch);
89	    await writeFile(CONFIG_PATH, JSON.stringify(merged, null, 4), 'utf-8');
90	
91	    // Propagate primary model change to existing sessions so they don't use stale overrides.
92	    // Sessions store a session-level `model` field that takes precedence over config defaults.
93	    // When the user changes the primary model, we need to clear these overrides.
