27	function deepMerge(target: Record<string, unknown>, source: Record<string, unknown>): Record<string, unknown> {
28	  const result = { ...target };
29	  for (const key of Object.keys(source)) {
30	    // Special handling for agents.list: merge by agent id
31	    if (key === 'list' && Array.isArray(source[key]) && Array.isArray(target[key])) {
32	      const sourceList = source[key] as AgentConfig[];
33	      const targetList = [...(target[key] as AgentConfig[])] as AgentConfig[];
34	      
35	      for (const sourceAgent of sourceList) {
36	        const existingIdx = targetList.findIndex(a => a.id === sourceAgent.id);
37	        if (existingIdx >= 0) {
38	          // Deep merge the existing agent with the source agent
39	          targetList[existingIdx] = deepMerge(
40	            targetList[existingIdx] as Record<string, unknown>,
41	            sourceAgent as Record<string, unknown>
42	          ) as AgentConfig;
43	        } else {
44	          // New agent, add it
