1	/**
2	 * OpenClaw Gateway Proxy
3	 * Proxies all requests to http://localhost:18789/{path}
4	 */
5	import { NextRequest, NextResponse } from 'next/server';
6	
7	const OPENCLAW_BASE = process.env.OPENCLAW_GATEWAY_URL ?? 'http://localhost:18789';
8	
9	async function proxy(request: NextRequest, { params }: { params: Promise<{ path: string[] }> }) {
10	  const { path } = await params;
11	  const targetPath = path.join('/');
12	  const url = new URL(request.url);
13	  const queryString = url.search;
14	  const target = `${OPENCLAW_BASE}/${targetPath}${queryString}`;
15	
16	  const headers: Record<string, string> = {
17	    'Accept': request.headers.get('accept') || 'application/json',
18	  };
19	
20	  const contentType = request.headers.get('content-type');
21	  if (contentType) headers['Content-Type'] = contentType;
22	
23	  const auth = request.headers.get('authorization');
24	  if (auth) headers['Authorization'] = auth;
25	
26	  try {
27	    const fetchOptions: RequestInit = {
28	      method: request.method,
29	      headers,
30	      signal: AbortSignal.timeout(30000),
31	    };
32	
33	    if (request.method !== 'GET' && request.method !== 'HEAD') {
34	      fetchOptions.body = await request.text();
35	    }
36	
37	    const response = await fetch(target, fetchOptions);
38	
39	    const responseHeaders = new Headers();
40	    response.headers.forEach((value, key) => {
41	      if (!['transfer-encoding', 'connection'].includes(key.toLowerCase())) {
42	        responseHeaders.set(key, value);
43	      }
44	    });
45	
46	    return new NextResponse(response.body, {
47	      status: response.status,
48	      statusText: response.statusText,
49	      headers: responseHeaders,
50	    });
51	  } catch (error) {
52	    return NextResponse.json(
53	      { error: 'OpenClaw gateway unreachable', detail: String(error) },
54	      { status: 502 }
55	    );
56	  }
57	}
58	
59	export const GET = proxy;
60	export const POST = proxy;
61	export const PUT = proxy;
62	export const PATCH = proxy;
63	export const DELETE = proxy;
64	
65	export async function OPTIONS() {
66	  return new NextResponse(null, {
67	    status: 204,
68	    headers: {
69	      'Access-Control-Allow-Origin': '*',
70	      'Access-Control-Allow-Methods': 'GET, POST, PUT, PATCH, DELETE, OPTIONS',
71	      'Access-Control-Allow-Headers': 'Content-Type, Authorization',
72	    },
73	  });
74	}
