11	
12	const DISCORD_API = 'https://discord.com/api/v10';
13	
14	function getBotToken(): string | null {
15	  try {
16	    const fs = require('fs');
17	    const config = JSON.parse(fs.readFileSync('/root/.openclaw/openclaw.json', 'utf-8'));
18	    return config?.channels?.discord?.token || null;
19	  } catch {
20	    return process.env.DISCORD_BOT_TOKEN || null;
21	  }
22	}
23	
24	const DEFAULT_DM_MESSAGE =
25	  `Hey! 👋 This is Pearl — your connection is confirmed!\n\n` +
26	  `You linked your Discord in PearlOS settings, so I can now reach you here. ` +
27	  `If you didn't do this, just ignore this message.\n\n` +
28	  `See you around! ✨`;
29	
30	export async function POST(req: NextRequest) {
31	  const token = getBotToken();
32	  if (!token) {
33	    return NextResponse.json({ error: 'Discord bot token not configured' }, { status: 500 });
34	  }
35	
36	  let body: Record<string, unknown>;
37	  try {
38	    body = await req.json();
39	  } catch {
40	    return NextResponse.json({ error: 'Invalid JSON body' }, { status: 400 });
41	  }
42	
43	  const userId = typeof body.userId === 'string' ? body.userId.trim() : '';
44	  const content = typeof body.content === 'string' && body.content.trim()
45	    ? body.content.trim()
46	    : DEFAULT_DM_MESSAGE;
47	
48	  if (!userId) {
49	    return NextResponse.json({ error: 'userId is required' }, { status: 400 });
50	  }
51	
52	  // Discord user IDs are snowflakes (17-20 digit numbers)
53	  if (!/^\d{17,20}$/.test(userId)) {
54	    return NextResponse.json(
55	      { error: 'Invalid Discord user ID. Please enter your numeric Discord user ID (e.g. 496705799687766016).' },
56	      { status: 400 },
57	    );
58	  }
59	
60	  if (content.length > 2000) {
61	    return NextResponse.json({ error: 'Message too long (max 2000 characters)' }, { status: 400 });
62	  }
