68	      headers: {
69	        Authorization: `Bot ${token}`,
70	        'Content-Type': 'application/json',
71	      },
72	      body: JSON.stringify({ recipient_id: userId }),
73	    });
74	
75	    if (!dmChannelRes.ok) {
76	      const text = await dmChannelRes.text();
77	      console.error('[discord/dm] Failed to open DM channel:', dmChannelRes.status, text);
78	      return NextResponse.json(
79	        { error: 'Could not open DM channel. Make sure the user ID is correct and the user shares a server with Pearl.' },
80	        { status: 502 },
81	      );
82	    }
83	
84	    const dmChannel = await dmChannelRes.json();
85	    const channelId: string = dmChannel.id;
86	
87	    // Step 2: Send the message in the DM channel
88	    const msgRes = await fetch(`${DISCORD_API}/channels/${channelId}/messages`, {
89	      method: 'POST',
90	      headers: {
91	        Authorization: `Bot ${token}`,
92	        'Content-Type': 'application/json',
93	      },
94	      body: JSON.stringify({ content }),
95	    });
96	
97	    if (!msgRes.ok) {
98	      const text = await msgRes.text();
99	      console.error('[discord/dm] Failed to send DM:', msgRes.status, text);
100	      return NextResponse.json(
101	        { error: 'DM channel opened but failed to send message. The user may have DMs disabled.' },
102	        { status: 502 },
103	      );
104	    }
105	
