1	import { NextRequest, NextResponse } from 'next/server';
2	
3	/**
4	 * /api/discord/channels — List text channels the bot can see in a guild.
5	 *
6	 * GET /api/discord/channels?guildId=<id>
7	 *
8	 * Returns JSON: { channels: [{ id, name, type, position }] }
9	 * Only returns text channels (type 0) and announcement channels (type 5).
10	 */
11	
12	const DISCORD_API = 'https://discord.com/api/v10';
13	const DEFAULT_GUILD_ID = '1471441655126167553';
14	
15	function getBotToken(): string | null {
16	  try {
17	    const fs = require('fs');
18	    const config = JSON.parse(fs.readFileSync('/root/.openclaw/openclaw.json', 'utf-8'));
19	    return config?.channels?.discord?.token || null;
20	  } catch {
21	    return process.env.DISCORD_BOT_TOKEN || null;
22	  }
23	}
24	
25	export async function GET(req: NextRequest) {
26	  const token = getBotToken();
27	  if (!token) {
28	    return NextResponse.json({ error: 'Discord bot token not configured' }, { status: 500 });
29	  }
30	
31	  const guildId = req.nextUrl.searchParams.get('guildId') || DEFAULT_GUILD_ID;
32	
33	  try {
34	    const res = await fetch(`${DISCORD_API}/guilds/${guildId}/channels`, {
35	      headers: { Authorization: `Bot ${token}` },
36	    });
37	
38	    if (!res.ok) {
39	      const text = await res.text();
40	      console.error('[discord/channels] Discord API error:', res.status, text);
41	      return NextResponse.json({ error: 'Discord API error', status: res.status }, { status: 502 });
42	    }
43	
44	    const allChannels = await res.json();
45	
46	    // Filter to text (0) and announcement (5) channels only, sorted by position
47	    const textChannels = allChannels
48	      .filter((ch: any) => ch.type === 0 || ch.type === 5)
49	      .sort((a: any, b: any) => a.position - b.position)
50	      .map((ch: any) => ({
51	        id: ch.id,
52	        name: ch.name,
53	        type: ch.type,
54	        position: ch.position,
55	        parentId: ch.parent_id || null,
56	      }));
57	
58	    return NextResponse.json({ channels: textChannels });
59	  } catch (err: any) {
60	    console.error('[discord/channels] Error:', err.message);
61	    return NextResponse.json({ error: 'Failed to fetch channels' }, { status: 500 });
62	  }
63	}
